const menuItems = [
    {
        id: 2, label: 'Personal Profile', href: '#', icon: ProfileSvg, isActive: true, subItems: [
            { label: 'Credit card info', icon: cardSvg, href: '#' },
        ],
    },
    // { id: 4, label: 'Credit card info', href: '#', icon: cardSvg, isSubItem: true },
    { id: 5, label: 'Checking', href: '#', icon: settingSvg },
    { id: 6, label: 'Sponsoring Preferences', href: '#', icon: settingSvg },
    { id: 8, label: 'Shipping Address', href: '#', icon: mapSvg },
    { id: 9, label: 'Enrollment Setting', href: '#', icon: settingSvg },
    { id: 10, label: 'Legacy Contact', href: '#', icon: contactSvg },
    { id: 11, label: 'Social Messenger', href: '#', icon: msgSvg },
];

const AccountHomePage: React.FC = () => {
    const [expandedItem, setExpandedItem] = useState<string | null>('Personal Profile');
    const [activeView, setActiveView] = useState<string | null>('Personal Profile');

    const handleToggle = (label: string | null) => {
        if (label !== expandedItem) {
            setExpandedItem(label);
        }
    };

    const handleViewChange = (label: string) => {
        setActiveView(label);
        if (label !== 'Personal Profile' && label !== 'Credit card info') {
            setExpandedItem(null); // Close submenu for unrelated items
        }
    };
    const renderView = () => {
        switch (activeView) {
            case 'Personal Profile':
                return <AccountSettingView />;
            case 'Credit card info':
                return <CardInfoView />;
            case 'Checking':
                return <CheckingView />;
            case 'Sponsoring Preferences':
                return <SponsoringPreferencesView />;
            case 'Shipping Address':
                return <ShippingAddressView />;
            case 'Enrollment Setting':
                return <EnrollmentSettingView />;
            case 'Legacy Contact':
                return <LegacyContactView />;
            case 'Social Messenger':
                return <SocialMessengerView />;
            default:
                return <p>Select a menu item to view details</p>;
        }
    };
    return (
        <section className={styles.mainBox}>
            <div className={styles.leftMenuOuter}>
                <div className={styles.leftMenuBox}>
                    <ul className={styles.mainBoxUl}>
                        {menuItems.map((item) => (
                            <li
                                key={item.label}
                                className={`${styles.mainBoxLi} `}
                            >
                                <Link href={item.href}
                                    className={`${styles.mainBoxLink} ${item.label === activeView ? styles.activeLi : ''} mainBoxLink ${item.label === activeView ? 'activeLi' : ''}`}
                                    onClick={(e) => {
                                        e.preventDefault();
                                        handleViewChange(item.label);
                                        handleToggle(item.subItems ? item.label : null);
                                    }}>
                                    <span>
                                        {item?.icon}
                                        {item?.label}
                                    </span>
                                    <span>
                                        {item.subItems && (
                                            expandedItem === item.label ? (
                                                <CaretUp size={24} className={styles.caretIcon} />
                                            ) : (
                                                <CaretDown size={24} className={styles.caretIcon} />
                                            )
                                        )}
                                    </span>
                                </Link>

                                {expandedItem === item.label && item.subItems && (
                                    <ul className={styles.subMenu}>
                                        {item.subItems.map((subItem) => (
                                            <li key={subItem.label}>
                                                <Link
                                                    href={subItem.href}
                                                    className={`${styles.subMenuLink} ${activeView === subItem.label ? styles.activeLi : ''
                                                        } subMenuLink`}
                                                    onClick={(e) => {
                                                        e.preventDefault();
                                                        handleViewChange(subItem.label);
                                                    }}
                                                >
                                                    {subItem?.icon}
                                                    {subItem.label}
                                                </Link>
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </li>
                        ))}
                    </ul>
                </div>
            </div>
            <div className={styles.rightSideBox}>
                {renderView()}
            </div>
        </section>
    );
};


export default AccountHomePage;
